export enum SendVoIpCallCancelMessageCancelReason {
  /** Call was answered on one of the devices, so call session is still active */
  Answered = 'answered',
  /** Whole call was already ended */
  Ended = 'ended'
}

export type SendVoIpCallCancelMessageData = {
  /**
   * Unique value for each call session between panel and resident (means same for different devices also).
   * Must be provided for correct work with multiple devices that use same voip call.
   * F.e. to cancel calls with CANCELED_CALL_MESSAGE_PUSH messages
   */
  callId: Scalars['String']['input'];
  /** Reason why call was canceled */
  reason: SendVoIpCallCancelMessageCancelReason;
};

export type SendVoIpCallCancelMessageInput = {
  /** Should be "addressKey" of B2CAppProperty / Property for which you want to send message */
  addressKey: Scalars['String']['input'];
  app: B2CAppWhereUniqueInput;
  callData: SendVoIpCallCancelMessageData;
  dv: Scalars['Int']['input'];
  sender: SenderFieldInput;
  /** Name of unit, same as in Property map */
  unitName: Scalars['String']['input'];
  /** Type of unit, same as in Property map */
  unitType: SendVoIpCallCancelMessageUnitType;
};

export enum SendVoIpCallCancelMessageUnitType {
  Apartment = 'apartment',
  Commercial = 'commercial',
  Flat = 'flat',
  Parking = 'parking',
  Warehouse = 'warehouse'
}

export type SendVoIpCallStartMessageData = {
  /** If you want your B2CApp to handle incoming VoIP call, provide this argument. */
  b2cAppCallData?: InputMaybe<SendVoIpCallStartMessageDataForCallHandlingByB2CApp>;
  /**
   * Unique value for each call session between panel and resident (means same for different devices also).
   * Must be provided for correct work with multiple devices that use same voip call.
   * F.e. to cancel calls with CANCELED_CALL_MESSAGE_PUSH messages
   */
  callId: Scalars['String']['input'];
  /** Meta information which helps you identify call. Not used right now. Will be sent to you server on answer button press. */
  callMeta?: InputMaybe<Scalars['JSON']['input']>;
  /** Identifier of caller device. Used to retrieve additional info from custom fields related to this device. */
  callerDeviceId?: InputMaybe<Scalars['String']['input']>;
  /** If you want mobile app to handle call (without your B2CApp), provide this argument. If "b2cAppCallData" and "nativeCallData" are provided together, native call is prioritized.  */
  nativeCallData?: InputMaybe<SendVoIpCallStartMessageDataForCallHandlingByNative>;
};

export type SendVoIpCallStartMessageDataForCallHandlingByB2CApp = {
  /** Data that will be provided to B2CApp. Object values will be serialized to a JSON string before sending. */
  B2CAppContext: Scalars['JSON']['input'];
};

export type SendVoIpCallStartMessageDataForCallHandlingByNative = {
  /** Preferred codec (usually vp8) */
  codec?: InputMaybe<Scalars['String']['input']>;
  /** Stun or turn servers which voip client will use */
  iceServers?: InputMaybe<Array<SendVoIpCallStartMessageDataIceServer>>;
  /** Address of sip server, which device should connect to */
  voipAddress: Scalars['String']['input'];
  /** Login for connection to sip server */
  voipLogin: Scalars['String']['input'];
  /** Panels and their commands to open. First one must be the main one. Multiple panels are in testing stage right now and may change */
  voipPanels: Array<SendVoIpCallStartMessageVoIpPanelParameters>;
  /** Password for connection to sip server */
  voipPassword: Scalars['String']['input'];
};

export type SendVoIpCallStartMessageDataIceServer = {
  /** Address for stun/turn/other server including protocol: "stun:...", "turn:...", "turns:..." */
  address: Scalars['String']['input'];
  login?: InputMaybe<Scalars['String']['input']>;
  password?: InputMaybe<Scalars['String']['input']>;
};

